// The static-site registry flow: registry.json + registry.json.minisig +
// plugins/<name>-<version>.component.wasm through the real machinery
// (loopback HTTP server, real install cache + config, real consent).
//
// minisign trust is validated two ways: (1) against fixtures generated by
// the REAL minisign binary (committed next to this test — the pure-Dart
// verifier must accept them), and (2) against signatures produced in-test
// with a fresh ed25519 key in minisign's wire format (tamper cases).
library;

import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:crypto/crypto.dart' as crypto;
import 'package:ed25519_edwards/ed25519_edwards.dart' as ed;
import 'package:test/test.dart';
import 'package:tina_plugin_registry/tina_plugin_registry.dart';

String _sha256(List<int> bytes) => crypto.sha256.convert(bytes).toString();

/// Serves a full site on [server]: the signed index over [entries] (in
/// minisign wire format signed by [secret]) plus [component] at every
/// entry's artifact path.
void _serve(HttpServer server, ed.PrivateKey secret, List<Object?> entries,
    Uint8List component,
    {int format = siteRegistryFormat}) {
  final indexBytes =
      utf8.encode(const JsonEncoder().convert(<String, Object?>{
    'registry_format': format,
    'updated': '2026-11-15T00:00:00Z',
    'entries': entries,
  }));
  final signature = ed.sign(secret, indexBytes);
  final sigFile = 'untrusted comment: test\n'
      '${base64.encode(Uint8List.fromList([0x45, 0x64, ...List.filled(8, 0x11), ...signature]))}\n'
      'trusted comment: test index\n';
  _serveRaw(server, Uint8List.fromList(indexBytes), sigFile, component);
}

void _serveRaw(
    HttpServer server, Uint8List indexBytes, String sigFile, Uint8List component) {
  server.listen((request) async {
    final path = request.uri.path;
    final response = request.response;
    List<int> body;
    if (path == '/registry.json') {
      body = indexBytes;
    } else if (path == '/registry.json.minisig') {
      body = utf8.encode(sigFile);
    } else if (path.startsWith('/plugins/')) {
      body = component;
    } else {
      response.statusCode = 404;
      await response.close();
      return;
    }
    response.headers.contentLength = body.length;
    response.add(body);
    await response.close();
  });
}

Map<String, Object?> _entryFor(Uint8List component, {required String path}) => {
      'name': 'tina/layout-solver',
      'version': '0.1.0',
      'description': 'solver',
      'abi': {
        'embedder_abi': 1,
        'world': 'tina:layout-app/layout-plugin@1.0.0',
      },
      'capabilities': <Map<String, Object?>>[],
      'artifact': {
        'sha256': _sha256(component),
        'size': component.length,
        'path': path,
      },
    };

void main() {
  final fixtures = Directory('test/fixtures');

  group('minisign verification (pure Dart vs the real tool)', () {
    test('accepts a signature produced by the real minisign binary', () {
      final message =
          File('${fixtures.path}/minisign_message.json').readAsBytesSync();
      final signature = File('${fixtures.path}/minisign_message.json.minisig')
          .readAsStringSync();
      final keyFile =
          File('${fixtures.path}/minisign_test.pub').readAsStringSync();
      final publicKey = minisignPublicKey(keyFile);
      expect(publicKey.length, 32);
      verifyMinisign(
          message: message,
          signatureFile: signature,
          minisignKeyFileOrBody: keyFile);
    });

    test('a prehashed (default-format) signature is refused with a re-sign '
        'instruction', () {
      final message =
          File('${fixtures.path}/minisign_message.json').readAsBytesSync();
      final legacy = File('${fixtures.path}/minisign_message.json.minisig')
          .readAsStringSync();
      // Swap the legacy tag bytes for the prehashed tag: the real default
      // format differs only in the tag (and the ph verification math).
      final body = Uint8List.fromList(base64.decode(legacy.split('\n')[1]));
      body[1] = 0x44;
      final prehashed =
          'untrusted comment: x\n${base64.encode(body)}\n';
      final keyFile =
          File('${fixtures.path}/minisign_test.pub').readAsStringSync();
      expect(
          () => verifyMinisign(
              message: message,
              signatureFile: prehashed,
              minisignKeyFileOrBody: keyFile),
          throwsA(isA<MinisignError>().having((e) => e.message, 'message',
              contains('minisign -S -l'))));
    });

    test('refuses a tampered message, a tampered signature, a wrong key',
        () {
      final message =
          File('${fixtures.path}/minisign_message.json').readAsBytesSync();
      final signature = File('${fixtures.path}/minisign_message.json.minisig')
          .readAsStringSync();
      final keyFile =
          File('${fixtures.path}/minisign_test.pub').readAsStringSync();

      final tamperedMessage = Uint8List.fromList(message);
      tamperedMessage[0] ^= 0x01;
      expect(
          () => verifyMinisign(
              message: tamperedMessage,
              signatureFile: signature,
              minisignKeyFileOrBody: keyFile),
          throwsA(isA<MinisignError>()));

      final tamperedSig =
          Uint8List.fromList(base64.decode(signature.split('\n')[1]));
      tamperedSig[20] ^= 0x01;
      final tamperedFile =
          'untrusted comment: x\n${base64.encode(tamperedSig)}\n';
      expect(
          () => verifyMinisign(
              message: message,
              signatureFile: tamperedFile,
              minisignKeyFileOrBody: keyFile),
          throwsA(isA<MinisignError>()));

      final wrongKey = ed.generateKey();
      final wrongKeyFile = 'untrusted comment: wrong\n'
          '${base64.encode(Uint8List.fromList([
            0x45, 0x64,
            ...List.filled(8, 0x99),
            ...(wrongKey.publicKey.bytes as List<int>),
          ]))}\n';
      expect(
          () => verifyMinisign(
              message: message,
              signatureFile: signature,
              minisignKeyFileOrBody: wrongKeyFile),
          throwsA(isA<MinisignError>()));
    });
  });

  group('the site registry flow (loopback HTTP, real machinery)', () {
    late HttpServer server;
    late Directory temp;
    late Uint8List component;
    late ed.PrivateKey secret;
    late String pubBody;

    setUpAll(() {
      component = Uint8List.fromList(
          File('${fixtures.path}/entity_decode.component.wasm')
              .readAsBytesSync());
    });

    setUp(() async {
      final pair = ed.generateKey();
      secret = pair.privateKey;
      pubBody = base64.encode(Uint8List.fromList([
        0x45, 0x64,
        ...List.filled(8, 0x11),
        ...(pair.publicKey.bytes as List<int>),
      ]));
      temp = await Directory.systemTemp.createTemp('site_registry_test');
      server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
    });

    tearDown(() async {
      await server.close(force: true);
      await temp.delete(recursive: true);
    });

    SiteRegistry client() => SiteRegistry(
        indexUrl: 'http://127.0.0.1:${server.port}',
        minisignKeyFileOrBody: pubBody);

    test('full add -> list -> remove loop, hash verified, consent recorded',
        () async {
      final entry = _entryFor(component,
          path: 'plugins/tina-layout-solver-0.1.0.component.wasm');
      _serve(server, secret, [entry], component);

      final config = RegistryConfig(File('${temp.path}/config'));
      final cache = PluginCache(root: Directory('${temp.path}/plugins'));
      final registry = client();

      final index = await registry.fetchIndex();
      expect(index.format, siteRegistryFormat);
      final resolved = index.latest('tina/layout-solver');
      expect(resolved, isNotNull);
      expect(index.latest('nope'), isNull);

      // Zero-capability entry: consent asks nothing and aborts nothing.
      final outcome = runNonInteractiveConsent(parseEntry(resolved!), const {});
      expect(outcome.aborted, isFalse);

      final installed = await installVerified(
        entry: resolved,
        artifactBytes: await registry.fetchArtifact(resolved),
        pinnedPublicKey: Uint8List(0),
        cache: cache,
        config: config,
        consent: (_) => outcome,
        activate: true,
        indexSignatureVerified: true,
      );
      expect(installed.name, 'tina/layout-solver');
      expect(installed.aborted, isFalse);

      final listed = await cache.list();
      expect(listed.single.name, 'tina/layout-solver');
      final data = config.read();
      expect(data.active, 'tina/layout-solver');
      expect(data.installed, ['tina/layout-solver@0.1.0']);
      // The component landed with the recorded bytes.
      expect(
          await File(listed.single.componentPath).readAsBytes(), component);

      await cache.remove('tina/layout-solver');
      expect(await cache.list(), isEmpty);
    });

    test('a tampered component (hash mismatch) is refused', () async {
      final tampered = Uint8List.fromList(component);
      tampered[100] ^= 0xff;
      final entry = _entryFor(component,
          path: 'plugins/tina-layout-solver-0.1.0.component.wasm');
      _serve(server, secret, [entry], tampered);

      final registry = client();
      final index = await registry.fetchIndex();
      final resolved = index.latest('tina/layout-solver')!;
      final bytes = await registry.fetchArtifact(resolved);

      final outcome = runNonInteractiveConsent(parseEntry(resolved), const {});
      await expectLater(
          installVerified(
            entry: resolved,
            artifactBytes: bytes,
            pinnedPublicKey: Uint8List(0),
            cache: PluginCache(root: Directory('${temp.path}/plugins')),
            config: RegistryConfig(File('${temp.path}/config')),
            consent: (_) => outcome,
            activate: true,
            indexSignatureVerified: true,
          ),
          throwsA(isA<VerificationError>()));
    });

    test('a bad index signature is refused before anything is trusted', () async {
      final entry = _entryFor(component,
          path: 'plugins/tina-layout-solver-0.1.0.component.wasm');
      final indexBytes = utf8.encode(const JsonEncoder().convert({
        'registry_format': 1,
        'updated': '',
        'entries': [entry],
      }));
      // Signed by a DIFFERENT key than the pinned one.
      final otherKey = ed.generateKey();
      final signature = ed.sign(otherKey.privateKey, indexBytes);
      final sigFile = 'untrusted comment: x\n'
          '${base64.encode(Uint8List.fromList([0x45, 0x64, ...List.filled(8, 0x22), ...signature]))}\n';
      _serveRaw(server, Uint8List.fromList(indexBytes), sigFile, component);

      await expectLater(client().fetchIndex(), throwsA(isA<RegistryClientError>()));
    });

    test('index format skew is refused with a clear message', () async {
      final entry = _entryFor(component,
          path: 'plugins/tina-layout-solver-0.1.0.component.wasm');
      final indexBytes = utf8.encode(const JsonEncoder().convert({
        'registry_format': 2,
        'updated': '',
        'entries': [entry],
      }));
      final signature = ed.sign(secret, indexBytes);
      final sigFile = 'untrusted comment: x\n'
          '${base64.encode(Uint8List.fromList([0x45, 0x64, ...List.filled(8, 0x11), ...signature]))}\n';
      _serveRaw(server, Uint8List.fromList(indexBytes), sigFile, component);

      await expectLater(client().fetchIndex(),
          throwsA(isA<RegistryClientError>().having(
              (e) => e.toString(), 'message',
              contains('newer than this client'))));
    });

    test('a required capability denied non-interactively refuses the install',
        () async {
      final entry = _entryFor(component,
          path: 'plugins/tina-layout-solver-0.1.0.component.wasm');
      entry['capabilities'] = [
        {'id': 'session.read-context', 'required': true}
      ];
      _serve(server, secret, [entry], component);

      final index = await client().fetchIndex();
      final resolved = index.latest('tina/layout-solver')!;

      final denied = runNonInteractiveConsent(parseEntry(resolved), const {});
      expect(denied.aborted, isTrue,
          reason: 'required capability not granted non-interactively');

      // With the explicit grant, the same entry consents and records it.
      final granted = runNonInteractiveConsent(
          parseEntry(resolved), const {'session.read-context'});
      expect(granted.aborted, isFalse);
      expect(granted.grantedStrings(), ['session.read-context']);
    });

    test('catalog-only entries are not downloadable', () async {
      _serve(server, secret, [
        {
          'name': 'tina/chat-tui',
          'version': '0.10.0',
          'description': 'included in the binary',
          'source': 'included',
        }
      ], component);

      final index = await client().fetchIndex();
      expect(index.latest('tina/chat-tui'), isNull,
          reason: 'catalog-only entries have no artifact to install');
      expect(VerifiedSiteIndex.downloadable(index.rawEntries.single), isFalse);
    });
  });
}
